package runtime

// Observational equivalence (paper §3.3.2, Definitions 31-35).
//
// The runtime's Snapshot is an OBSERVATION DATA STRUCTURE; it is not itself the
// equivalence relation of the paper. This file builds that relation explicitly,
// following the paper rather than inventing an ad-hoc "ignore more fields"
// canonicalization:
//
//   - Def 31/32: the equivalence at a key ≃ₖ is generated by the OBSERVATIONS
//     available at that key (finite tests of forward maps and yielded inverses).
//     It is the COARSEST equivalence that every operation of the key respects.
//   - Def 33: two coeffect-contexts are related at a key set S when they bind
//     the same keys of S to related values:
//        σ ≃_S σ' ≔ dom(σ)∩S = dom(σ')∩S ∧ ∀k∈dom(σ)∩S. σ(k) ≃ₖ σ'(k)
//     and context states are related by their coeffect projections.
//   - Def 34/35: the relation lifts through products/functions/Maybe and is a
//     PARTIAL equivalence on maps/iterators (symmetric + transitive; respect
//     is a condition, not a given).
//
// The key insight for a runtime realization: what an observer can OBSERVE at a
// key is exactly the fields of that key's provider record that operations can
// reach. We let each key register an ObservationSpec declaring those fields;
// equivalence compares only within that boundary. Two snapshots differing in a
// field no operation at that key can observe are related — precisely the paper's
// "compare behavior, not representation".

import "sort"

// ObservedField names one observable facet of a key's provider record (paper
// Def 29: the operations at a key define what an observer of a value can run).
type ObservedField string

const (
	// ObserveAvailability — whether the capability is satisfiable (State +
	// Retiring). Every provide/require operation observes this.
	ObserveAvailability ObservedField = "availability"
	// ObserveOwnerGeneration — which Fiber/Activation currently owns the key.
	// Dependency capture/withdrawal observes this (Thm 70/80 binding identity).
	ObserveOwnerGeneration ObservedField = "owner-generation"
	// ObserveNamespace — which realm (ScopeID) the key resolves/provides in
	// (paper Def 24 per-key realm ρ). Isolation/Rehome operations observe this.
	ObserveNamespace ObservedField = "namespace"
)

// ObservationSpec is one key's observation boundary: the set of fields that
// operations at that key can distinguish. Equivalence compares ONLY these
// fields; all other representation (activation counters, generation names,
// journal offsets, heap layout) is outside the relation (Def 33 final clause).
type ObservationSpec struct {
	// Key is the string form of the capability (CapabilityKey.String()), which
	// is how Snapshot observations name keys.
	Key    string
	Fields map[ObservedField]bool
}

// ObservationModel collects the per-key observation boundaries. A key with no
// explicit spec defaults to the minimal boundary {ObserveAvailability} —
// the least an observer of any capability can see.
//
// The model is IMMUTABLE after construction (built once per test/component
// composition); it is safe for concurrent reads.
type ObservationModel struct {
	specs map[string]ObservationSpec
}

// NewObservationModel builds a model from explicit per-key specs.
func NewObservationModel(specs ...ObservationSpec) *ObservationModel {
	m := &ObservationModel{specs: make(map[string]ObservationSpec, len(specs))}
	for _, s := range specs {
		cp := ObservationSpec{Key: s.Key, Fields: make(map[ObservedField]bool, len(s.Fields))}
		for f := range s.Fields {
			cp.Fields[f] = true
		}
		m.specs[s.Key] = cp
	}
	return m
}

// fieldsFor returns the observation boundary for key (default minimal).
func (m *ObservationModel) fieldsFor(k string) map[ObservedField]bool {
	if m == nil {
		return map[ObservedField]bool{ObserveAvailability: true}
	}
	if s, ok := m.specs[k]; ok {
		return s.Fields
	}
	return map[ObservedField]bool{ObserveAvailability: true}
}

// providerAt finds the provider record for key in an observation (the first
// non-retiring record wins; a retiring-only record is still observable as such).
func providerAt(o RuntimeSnapshot, k string) (ProviderView, bool) {
	for _, p := range o.Providers {
		if p.Key == k {
			return p, true
		}
	}
	return ProviderView{}, false
}

// EquivalentValues is the per-key relation ≃ₖ (Def 31/32): two provider
// records are related when they agree on every field the key's operations can
// observe. State+Retiring collapse into availability; the exact owner IDs are
// compared only when the key declares ObserveOwnerGeneration (so a generative
// activation-name change is outside the relation unless observed — Def 33).
func (m *ObservationModel) EquivalentValues(k string, a, b ProviderView) bool {
	f := m.fieldsFor(k)
	if f[ObserveAvailability] {
		if a.Retiring != b.Retiring {
			return false
		}
		// A record is "available" exactly while its owner is Active and it is
		// not retiring. Comparing availability rather than raw state lets two
		// equivalent-but-differently-labelled states relate.
		if available(a) != available(b) {
			return false
		}
	}
	if f[ObserveOwnerGeneration] {
		if a.OwnerFiberID != b.OwnerFiberID || a.OwnerActivationID != b.OwnerActivationID {
			return false
		}
	}
	if f[ObserveNamespace] && a.ScopeID != b.ScopeID {
		return false
	}
	return true
}

func available(p ProviderView) bool {
	return !p.Retiring && p.State == StateActive
}

// RelevantKeys returns the sorted capabilities in the intersection
// dom(σ)∩S (Def 33). Keys are compared by string identity of CapabilityKey.
// S == nil means the full key set K (≃ with no subscript).
func RelevantKeys(o RuntimeSnapshot, S []CapabilityKey) []string {
	var filter map[string]bool
	if S != nil {
		filter = make(map[string]bool, len(S))
		for _, k := range S {
			filter[k.String()] = true
		}
	}
	seen := make(map[string]bool)
	for _, p := range o.Providers {
		k := p.Key
		if filter != nil && !filter[k] {
			continue
		}
		seen[k] = true
	}
	out := make([]string, 0, len(seen))
	for k := range seen {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// EquivalentAt implements Definition 33: σ ≃_S σ' when the key domains
// intersect S equally and, for every such key, the provider values are ≃ₖ.
// The non-provider parts of a runtime snapshot (effect counters, fiber IDs of
// unrelated components) are outside the relation — they are not bound by a
// key (Def 33 "the part of a state that no key binds is forgotten").
func (m *ObservationModel) EquivalentAt(a, b RuntimeSnapshot, S []CapabilityKey) bool {
	ka, kb := RelevantKeys(a, S), RelevantKeys(b, S)
	if len(ka) != len(kb) {
		return false // dom(σ)∩S = dom(σ')∩S
	}
	for i := range ka {
		if ka[i] != kb[i] {
			return false
		}
		pa, oka := providerAt(a, ka[i])
		pb, okb := providerAt(b, kb[i])
		if oka != okb || !oka {
			return false
		}
		if !m.EquivalentValues(ka[i], pa, pb) {
			return false // ∀k ∈ dom∩S. σ(k) ≃ₖ σ'(k)
		}
	}
	return true
}
